def solve(values):
    distinct = set(values)
    if len(distinct) < 2:
        return None
    largest = max(distinct)
    distinct.discard(largest)
    return max(distinct)

def solve(values):
    if not values:
        return 0

    max_run = 1
    current_run = 1

    for i in range(1, len(values)):
        if values[i] > values[i - 1]:
            current_run += 1
            max_run = max(max_run, current_run)
        else:
            current_run = 1

    return max_run

